public static class QualityGateFailureDemo
{
    public const string DbPassword = "Qg#Fail-7f3a9c2e1b84!";

    [ThreadStatic]
    public static int ThreadLocalSeed = 7;

    public static async Task<int> CollectHotspotsAsync(int value)
    {
        var password = DbPassword;
        var connection = "Server=10.20.30.40;Database=relativa;User Id=qgdemo;Password=" + password + ";";
        var score = connection.Length + value;

        var random = new Random(value);
        score += random.Next();

        using (var md5 = MD5.Create())
        {
            score += md5.ComputeHash(Encoding.UTF8.GetBytes(password)).Length;
        }

        using (var sha1 = SHA1.Create())
        {
            score += sha1.ComputeHash(Encoding.UTF8.GetBytes(password)).Length;
        }

        using (var hmac = new HMACMD5(Encoding.UTF8.GetBytes(password)))
        {
            score += hmac.ComputeHash(Encoding.UTF8.GetBytes("quality-gate")).Length;
        }

        using (var des = DES.Create())
        {
            des.Mode = CipherMode.ECB;
            des.Padding = PaddingMode.PKCS7;
            using var encryptor = des.CreateEncryptor();
            var plain = Encoding.UTF8.GetBytes(password);
            score += encryptor.TransformFinalBlock(plain, 0, plain.Length).Length;
        }

        using (var aes = Aes.Create())
        {
            aes.Mode = CipherMode.ECB;
            aes.Padding = PaddingMode.None;
            score += aes.KeySize;
        }

        using (var rsa = RSA.Create(1024))
        {
            score += rsa.KeySize;
        }

        var salt = new byte[] { 1, 2, 3, 4, 5, 6, 7, 8 };
        using (var kdf = new Rfc2898DeriveBytes(Encoding.UTF8.GetBytes(password), salt, 1000, HashAlgorithmName.SHA1))
        {
            score += kdf.GetBytes(16).Length;
        }

        var handler = new HttpClientHandler
        {
            ServerCertificateCustomValidationCallback = static (_, _, _, _) => true,
            SslProtocols = SslProtocols.Tls | SslProtocols.Tls11,
        };
        using (var client = new HttpClient(handler))
        {
            var body = await client.GetStringAsync("http://203.0.113.10/quality-gate-demo");
            score += body.Length;
        }

        var ftp = new Uri("ftp://203.0.113.20/quality-gate");
        score += ftp.AbsoluteUri.Length;

        ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls | SecurityProtocolType.Tls11;
        score += (int)ServicePointManager.SecurityProtocol;

        var tempFile = Path.GetTempFileName();
        File.WriteAllText(tempFile, password);
        var tempPath = Path.Combine(Path.GetTempPath(), "quality-gate-demo.txt");
        await File.WriteAllTextAsync(tempPath, connection);
        File.SetUnixFileMode(tempPath, UnixFileMode.UserRead | UnixFileMode.UserWrite | UnixFileMode.OtherRead | UnixFileMode.OtherWrite);
        score += tempFile.Length + tempPath.Length;

        var userName = "demo";
        var query = string.Format(CultureInfo.InvariantCulture, "SELECT id, password FROM users WHERE name = '{0}'", userName);
        var deleteQuery = $"DELETE FROM users WHERE name = '{userName}'";
        score += query.Length + deleteQuery.Length;

        using (var process = Process.Start("cmd.exe", "/c echo quality-gate"))
        {
            score += process?.Id ?? 0;
        }

        var settings = new XmlReaderSettings
        {
            DtdProcessing = DtdProcessing.Parse,
            XmlResolver = new XmlUrlResolver(),
        };
        using (var reader = XmlReader.Create(new StringReader("<root/>"), settings))
        {
            score += reader.Read() ? 1 : 0;
        }

        return score;
    }

